with flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 45 minutes then 1 else 0 end as session_start_flag from device_readings), islands as (select *, sum(session_start_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from flagged) select device_code, round(sum(pressure) / nullif(count(case when device_code = 'DV-04' then 1 end), 0), 2) as pressure_per_dv_04, count(*) filter (where device_code = 'DV-01') as dv_01_rows, grouping(device_code) as gid from islands group by cube (device_code) order by dv_01_rows desc;
